head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDDST37005";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jlddst37005.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_request
 * @description request 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_request = async function () {
    // ⛔주소를 정할 수 없다 — as-is 문서 위치를 못 찾았다(⛔못 쟀다 — as-is JSP 위치 미상).
    //   추정 주소로 내보내면 «엉뚱한 곳으로 조용히» 나간다. 불릴 때 드러나게 실패시킨다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "제출 주소를 찾지 못했습니다(전환 미완) — null"
    throw { bizMessage: "제출 주소를 찾지 못했습니다(전환 미완) — null", unresolved: "action:null" };
};

/**
 * @method
 * @name request
 * @description request 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.request = async function () {
    (document.form1 || { elements: [] }).action = "null";
    (document.form1 || { elements: [] }).method = "post";
    await scwin.tx_request();
};
